/* Presentation only: native controls, form values, events and permissions stay intact. */
(() => {
    'use strict';
    if (!document.body.classList.contains('module-workspace')) return;
    const pack = document.querySelector('[data-konta-workspace-icons]');
    if (!pack) return;
    const icons = JSON.parse(pack.textContent);
    const templates = new Map();
    for (const [name, markup] of Object.entries(icons)) {
        const template = document.createElement('template');
        // This markup is generated by the server's static icon catalogue.
        template.innerHTML = markup;
        templates.set(name, template.content.firstElementChild);
    }
    const normalize = value => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
    const savedText=cell=>{
        const select=cell.querySelector('select');if(select)return select.selectedOptions[0]?.textContent.trim()||'—';
        const input=cell.querySelector('input:not([type=hidden]),textarea');return input?input.value:cell.textContent.trim();
    };
    function decorate(root) {
        const savedProducts=[...root.querySelectorAll('fieldset[disabled] select[data-line-product],fieldset[disabled] select[data-order-product]')];
        for(const select of savedProducts){
            if(select.dataset.kontaProductRendered)continue;
            select.dataset.kontaProductRendered='true';
            const control=select.closest('.searchable-select')||select;
            control.classList.add('konta-saved-product-control');
            const value=document.createElement('span');value.className='konta-saved-product';value.textContent=select.selectedOptions[0]?.textContent.trim()||'—';
            control.after(value);
        }
        for(const table of document.querySelectorAll('.konta-readonly-lines')){
            table.setAttribute('role','table');
            if(table.tHead)table.tHead.setAttribute('role','rowgroup');
            for(const body of table.tBodies)body.setAttribute('role','rowgroup');
            for(const row of table.rows){row.setAttribute('role','row');for(const cell of row.cells)cell.setAttribute('role',cell.tagName==='TH'?'columnheader':'cell');}
            for(const row of [...table.tBodies].flatMap(body=>[...body.rows])){
                if(row.dataset.kontaLineRendered)continue;
                const name=row.querySelector('.konta-line-name');if(!name)continue;
                row.dataset.kontaLineRendered='true';
                const extras=[...row.querySelectorAll('.konta-line-extra')];
                if(extras.length){
                    const details=document.createElement('details');details.className='konta-row-details';
                    const summary=document.createElement('summary');summary.textContent='Ver detalle';details.append(summary);
                    const list=document.createElement('dl');
                    for(const cell of extras){const group=document.createElement('div'),label=document.createElement('dt'),value=document.createElement('dd');label.textContent=cell.dataset.columnLabel;value.textContent=savedText(cell);group.append(label,value);list.append(group);}
                    details.append(list);name.append(details);
                }
                for(const cell of row.querySelectorAll('.konta-line-quantity,.konta-line-total')){
                    if(!cell.querySelector('input,select,textarea'))continue;
                    const value=document.createElement('span');value.className='konta-saved-scalar';value.textContent=savedText(cell);cell.append(value);
                }
            }
        }
        const emptySelector = '.direct-history>p,[data-direct-empty],.restaurant-empty-symbol,.restaurant-pos-cart-empty>span[aria-hidden]';
        const empties = [...root.querySelectorAll(emptySelector)];
        if (root.matches?.(emptySelector)) empties.push(root);
        for (const empty of empties) {
            if (empty.dataset.kontaEmpty) continue;
            empty.dataset.kontaEmpty = 'true';
            const icon = templates.get('empty').cloneNode(true);
            icon.classList.add('konta-empty-icon');
            if (empty.matches('.restaurant-empty-symbol,.restaurant-pos-cart-empty>span')) empty.replaceChildren(icon);
            else { empty.classList.add('konta-empty-message'); empty.prepend(icon); }
        }
        const selector = '.contact-button,.record-edit-link,.overview-link,.back-link,.restaurant-workspace .button';
        const controls = [...root.querySelectorAll(selector)];
        if (root.matches?.(selector)) controls.unshift(root);
        for (const control of controls) {
            if (control.querySelector('svg') || control.matches('input,.contact-icon-button,[data-konta-iconized]')) continue;
            const text = normalize(control.textContent);
            let kind = null;
            if (/^[+]?\s*(nuevo|nueva|agregar|anadir|crear)/.test(text)) kind = 'plus';
            else if (/^guardar/.test(text)) kind = 'save';
            else if (/^(←\s*)?(volver|contactos$|ordenes de venta$|facturas$|modulos$)/.test(text) && control.matches('a')) kind = 'back';
            else if (/^(cerrar|cancelar$|×$)/.test(text)) kind = 'close';
            else if (/^editar/.test(text)) kind = 'edit';
            else if (/^(filtrar|aplicar filtros)/.test(text)) kind = 'filter';
            else if (/^(limpiar|actualizar|restablecer)/.test(text)) kind = 'refresh';
            else if (/^(exportar|descargar)/.test(text)) kind = 'download';
            else if (/^(importar|subir)/.test(text)) kind = 'upload';
            else if (/^(confirmar|validar|aprobar|continuar)/.test(text)) kind = 'check';
            else if (/^registrar (pago|cobro|reembolso)/.test(text)) kind = 'closing';
            if (!kind) continue;
            if (kind === 'close' && text === '×' && !control.hasAttribute('aria-label')) control.setAttribute('aria-label', 'Cerrar');
            for (const child of control.childNodes) {
                if (child.nodeType !== Node.TEXT_NODE) continue;
                if (kind === 'plus') child.textContent = child.textContent.replace(/^(\s*)\+\s*/, '$1');
                if (kind === 'back') child.textContent = child.textContent.replace(/^(\s*)←\s*/, '$1');
                if (kind === 'close' && text === '×') child.textContent = '';
                break;
            }
            control.prepend(templates.get(kind).cloneNode(true));
            control.dataset.kontaIconized = kind;
            if(kind==='save'&&control.closest('.contact-form-actions')){
                const label=control.textContent.trim();
                if(!control.hasAttribute('aria-label'))control.setAttribute('aria-label',label);
                const full=document.createElement('span');full.className='konta-save-label';
                // Keep the native accessible name; shorten only the visible caption on narrow phones.
                for(const child of [...control.childNodes])if(child.nodeType===Node.TEXT_NODE)full.append(child);
                const compact=document.createElement('span');compact.className='konta-save-compact';compact.textContent='Guardar';compact.setAttribute('aria-hidden','true');
                control.append(full,compact);
            }
        }
        const badges = [...root.querySelectorAll('.contact-tag:not([data-tone])')];
        if (root.matches?.('.contact-tag:not([data-tone])')) badges.push(root);
        for (const badge of badges) {
            const text = normalize(badge.textContent);
            let tone = null;
            if (/pendiente|en revision|parcial/.test(text)) tone = 'warning';
            else if (/^(cancelad[oa]|rechazad[oa]|revertid[oa]|vencid[oa]|error)$/.test(text)) tone = 'danger';
            else if (/^(activ[oa]|aprobad[oa]|confirmad[oa]|transferid[oa]|pagad[oa]|revisad[oa])$/.test(text)) tone = 'success';
            if (tone) { badge.classList.add('workspace-status'); badge.dataset.tone = tone; }
        }
        for (const bar of document.querySelectorAll('.document-actions,.contact-form-actions,.invoice-wizard-footer,.restaurant-actions')) {
            const choices = [...bar.querySelectorAll('.contact-button-primary,.button-primary')];
            const available = choices.filter(button => !button.disabled && !button.closest('[hidden]'));
            const primary = available.find(button => button.dataset.kontaIconized === 'check') || available[0] || choices[0];
            for (const button of choices) button.classList.toggle('konta-secondary-action', button !== primary);
        }
    }
    decorate(document);
    document.addEventListener('live-filters:updated', event => decorate(event.target));
    // Additions include invoice dialogs, restaurant actions and product lines.
    const observer = new MutationObserver(records => {
        for (const record of records) for (const node of record.addedNodes) {
            if (node.nodeType === Node.ELEMENT_NODE && !node.matches('svg,svg *')) decorate(node);
        }
    });
    observer.observe(document.body, {childList:true, subtree:true});
})();
